var maximumJumps = function(nums, target) {
    const n = nums.length;
    const dp = new Array(n).fill(-1);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        if (dp[i] === -1) continue;
        for (let j = i + 1; j < n; j++) {
            if (Math.abs(nums[j] - nums[i]) <= target) {
                if (dp[i] + 1 > dp[j]) {
                    dp[j] = dp[i] + 1;
                }
            }
        }
    }
    return dp[n - 1];
};
